using System.Collections;
using FMOD.Studio;
using LittleLeo;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

public class PlayerSpriteControl : SpriteControl
{
	[Header("Decayed Animation")]
	[SerializeField]
	private float shakeAmount;

	[SerializeField]
	private float decayedDuration;

	[SerializeField]
	private float completelyDecayedDuration;

	[SerializeField]
	private FloatReference delayToUpdateCorruptionMeterFloatReference;

	[SerializeField]
	private FloatReference loseHeartLoseGameVFXDelayFloatReference;

	[Header("Corrupted Animation")]
	[SerializeField]
	private float corruptShakeDuration;

	[SerializeField]
	private float corruptShakeAmount;

	[Header("Components")]
	[SerializeField]
	private PlayerCorruptionStats playerCorruptionStats;

	[SerializeField]
	private UnitEffects unitEffects;

	[Header("Events")]
	[SerializeField]
	private VoidEvent OnPlayerLoseHeart;

	private bool overrideIsDefeated;

	private bool lostHeartDontPlayUsingDiceSFX;

	private EventInstance playerActionSFXEventInstance;

	public void SetOverrideIsDefeated(bool value)
	{
		overrideIsDefeated = value;
	}

	private void Start()
	{
		Character currentCharacter = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter;
		animationData = currentCharacter.AnimationData;
		if (currentCharacter.EnableUnitsMiscData)
		{
			enableUnitsMiscData = true;
			unitsMiscData = currentCharacter.UnitsMiscData;
		}
		SpawnSkeletonAnimation();
		ResetOutlineBrightness();
	}

	protected override void SpawnSkeletonAnimation()
	{
		base.SpawnSkeletonAnimation();
		skeletonTransform.position = base.transform.position;
		skeletonMeshRenderer.SetRendererFloat(materialPropertyBlock, "_EffectTexAlpha", 0f);
	}

	public void PlayAttackOrSkillAnimation()
	{
		ReferenceSingleton<CoroutineHandler>.Instance.Run(TryPlayUsingDiceSFX());
		AnimationType[] animationTypeToChecks = new AnimationType[2]
		{
			AnimationType.Critical,
			AnimationType.Dodge
		};
		PlayAnimationForcedIfSpecificAnimationIsNotPlaying(AnimationType.Attack, animationTypeToChecks, AnimationChangeType.ReturnToIdleAnimation);
	}

	private IEnumerator TryPlayUsingDiceSFX()
	{
		yield return InvokeAlternatives.WaitForFrames(6);
		if (!lostHeartDontPlayUsingDiceSFX && (bool)ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterSFXData)
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFXWithEventInstanceReference(ref playerActionSFXEventInstance, ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterSFXData.UsingDice);
		}
	}

	public void OnPlayerLoseHeartAnimation()
	{
		CoroutineUtility.ShakeRoutine(this, animationSkeleton.transform, decayedDuration, shakeAmount);
		skeletonMeshRenderer.SetRendererFloat(materialPropertyBlock, "_EffectTexAlpha", 1f);
		PlayAnimationForced(AnimationType.LoseHeart, AnimationChangeType.ReturnToIdleAnimation, delegate
		{
			skeletonMeshRenderer.TweenFadeRendererFloat(materialPropertyBlock, "_EffectTexAlpha", 1f, 0f, 0.4f);
			StartCoroutine(lightSprite.material.TweenFloatProperty("_TextTween", 0f, 0.4f));
		});
	}

	public void OnPlayerCompletelyCorruptedAnimation()
	{
		unitEffects.RemoveAllEffectsVFX();
		unitEffects.RemoveAllEffectWithoutCallbacks();
		OnReceiveFatalDamage();
	}

	public void OnLoseHeartPrevented()
	{
		PlayAnimation(AnimationType.Idle, AnimationChangeType.StayInTheNewAnimationLooping);
		StartCoroutine(lightSprite.material.TweenFloatProperty("_TextTween", 0f, 0.4f));
	}

	public override void OnReceivePurify()
	{
		base.OnReceivePurify();
		if (playerCorruptionStats.CompletelyCorrupted)
		{
			PlayAnimationForced(AnimationType.Idle, AnimationChangeType.StayInTheNewAnimationLooping);
		}
	}

	public override void OnReceiveCorruption()
	{
		OnReceiveCorruptionAndShake();
		AnimationType[] animationTypeToChecks = new AnimationType[4]
		{
			AnimationType.Attack,
			AnimationType.Critical,
			AnimationType.Dodge,
			AnimationType.Skill
		};
		PlayAnimationForcedIfSpecificAnimationIsNotPlaying(AnimationType.ReceiveDamage, animationTypeToChecks, AnimationChangeType.ReturnToIdleAnimation);
		SetMixDuration(0f);
	}

	private void ReceiveCorruptionShake()
	{
		CoroutineUtility.ShakeRoutine(this, animationSkeleton.transform, corruptShakeDuration, corruptShakeAmount);
	}

	public void OnReceiveCorruptionAndLoseHeartPlayReceiveDamage()
	{
		lostHeartDontPlayUsingDiceSFX = true;
		OnReceiveCorruptionAndShake();
		PlayAnimationForced(AnimationType.ReceiveDamage, AnimationChangeType.StayInTheNewAnimationNotLooping);
		SetMixDuration(0f);
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.SetPlayerLoseHeartCoroutine(PlayerLoseHeartCoroutine());
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
	}

	private IEnumerator PlayerLoseHeartCoroutine()
	{
		Debug.Log("PlayerLoseHeartCoroutine: Start");
		if (playerCorruptionStats.IsDefeated() || overrideIsDefeated)
		{
			yield return new WaitForSeconds(1f);
			StartCoroutine(lightSprite.material.TweenFloatProperty("_TextTween", 1f, 0.4f));
			bool flag = (unitEffects as PlayerEffects).IsPlayerIndigoSoulWithoutDecrease();
			OnPlayerLoseHeart.Raise();
			float num = 0f;
			if (ReferenceSingleton<VFXHandler>.Instance.IsVFXEnabled() && !flag)
			{
				num = loseHeartLoseGameVFXDelayFloatReference.Value;
			}
			yield return new WaitForSeconds(delayToUpdateCorruptionMeterFloatReference.Value + num);
		}
		playerCorruptionStats.SetCompletelyCorrupted(value: false);
		SetOverrideIsDefeated(value: false);
		lostHeartDontPlayUsingDiceSFX = false;
		Debug.Log("PlayerLoseHeartCoroutine: End");
	}

	public void OnReceiveCorruptionAndShake()
	{
		base.OnReceiveCorruption();
		StartCoroutine(TryPlayReceivingCorruptionSFX());
		ReceiveCorruptionShake();
	}

	private IEnumerator TryPlayReceivingCorruptionSFX()
	{
		yield return InvokeAlternatives.WaitForFrames(6);
		if ((bool)ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterSFXData && !ReferenceSingleton<SFXHandler>.Instance.IsSFXPlaying(ref playerActionSFXEventInstance))
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFXWithEventInstanceReference(ref ReferenceSingleton<SFXHandler>.Instance.PlayerReceivingCorruptionEventInstance, ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterSFXData.ReceivingCorruption);
		}
	}

	public override void OnReceiveFatalDamage()
	{
		CoroutineUtility.ShakeRoutine(this, animationSkeleton.transform, completelyDecayedDuration, shakeAmount);
		skeletonMeshRenderer.SetRendererFloat(materialPropertyBlock, "_EffectTexAlpha", 1f);
		StartCoroutine(lightSprite.material.TweenFloatProperty("_TextTween", 1f, 0.4f));
		PlayAnimationForced(AnimationType.Die, AnimationChangeType.StayInTheNewAnimationNotLooping, delegate
		{
			PlayAnimationForced(AnimationType.DieIdle, AnimationChangeType.StayInTheNewAnimationLooping);
		});
	}
}
